// ET-014 PR-2: the ET-005b synthetic simulator scenarios replayed through the trip reducer and a first-insert storage
// model (tests/shared/trip-replay.ts), compared with hand-written tests/fixtures/simulator-v1/<id>.trip.expected.json.
// Each expectation is written from the scenario definition, its hand-written wire expectation, docs/trips.md and the
// T1–T20 decisions; none is generated by this code. Seeded identifiers and trip UUIDs appear as labels: a trip is
// `trip@<eventSeq of its job configuration>`, derived here with an independent node:crypto implementation of T4.
import {createHash} from 'node:crypto';
import {existsSync, readFileSync} from 'node:fs';
import {describe, expect, it} from 'vitest';
import {tripView, type TripSummaryView} from '../../packages/telemetry-core/src/index';
import {readFixtureFile} from '../../tools/telemetry-simulator/src/fixture-file';
import {replayV1} from '../../tools/telemetry-simulator/src/v1/replay';
import {seededId} from '../../tools/telemetry-simulator/src/v1/source';
import {SIMULATOR_V1_DIR, scenarioPath} from '../shared/simulator-v1-expected';
import {replayTrips, type TripReplay} from '../shared/trip-replay';

const SCENARIOS = ['normal-delivery', 'app-absent-hydration', 'save-load', 'timers-truck-refuel', 'ferry-train', 'sleep-teleport', 'quick-job-profile-change',
  'clock-change-suspend', 'reconnect-lost-ack', 'crash-before-commit', 'crash-after-commit', 'retention-expired'];
const tripExpectedPath = (id: string) => `${SIMULATOR_V1_DIR}/${id}.trip.expected.json`;
interface TripExpected {scenario: string; basis: string[]; authoredFrom: string[]; trips: unknown[]; attributions: unknown[]; intervals: unknown[]; coverage: unknown; view: unknown}

function labels(seed: string): Map<string, string> {
  const map = new Map<string, string>(), session = seededId(seed, 'plugin-session');
  for (const label of ['plugin-session', 'process-instance', 'capture-clock']) map.set(seededId(seed, label), label);
  for (let n = 0; n < 20; n++) map.set(seededId(seed, `game-clock-${n}`), `game-clock-${n}`);
  for (let seq = 1; seq <= 200; seq++) {
    const h = createHash('sha256').update(`ets2telemetry-trip-v1:${session}:${seq}`, 'utf8').digest('hex');
    map.set(`${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`, `trip@${seq}`);
  }
  return map;
}
function trip(view: TripSummaryView | null) {
  if (view === null) return null;
  return {trip: view.tripUuid, recordingCompleteness: view.recordingCompleteness, observedDistanceM: view.observedDistanceM, fuelUsedL: view.fuelUsedL,
    refuelledL: view.refuelledL, refuels: view.refuels};
}
/** The stored rows and the final view of the scenario's game, with seeded identifiers replaced by labels. */
function summarize(replay: TripReplay, seed: string, game: 'ets2' | 'ats') {
  const s = replay.storage, view = tripView(replay.state, game), map = labels(seed);
  const out = {
    trips: s.trips.map(t => ({trip: t.tripUuid, jobConfigurationEventSeq: t.jobConfigurationEventSeq, truckConfigurationEventSeq: t.truckConfigurationEventSeq,
      trailerConfigurationEventSeqs: t.trailerConfigurationEventSeqs, openedEventSeq: t.openedEventSeq, gameMode: t.gameMode, gameModeAmbiguous: t.gameModeAmbiguous,
      outcome: t.outcome, outcomeEventSeq: t.outcomeEventSeq, closeReason: t.closeReason, recordingCompleteness: t.recordingCompleteness, startedUtcMs: t.startedUtcMs,
      endedUtcMs: t.endedUtcMs, observedDistanceM: t.observedDistanceM})),
    attributions: s.attributions.map(a => ({eventSeq: a.eventSeq, trip: a.tripUuid, attribution: a.attribution})),
    intervals: s.intervals.map(i => {
      const {tripUuid, ...rest} = i, row: Record<string, unknown> = {trip: tripUuid ?? null, ...rest};
      delete row.pluginSessionId;
      return row;
    }),
    coverage: {committedThroughEventSeq: s.committedThrough(seededId(seed, 'plugin-session')), ...s.statuses},
    view: {phase: view.phase, untrackedJob: view.untrackedJob, current: trip(view.current),
      lastClosed: view.lastClosed === null ? null : {...trip(view.lastClosed), outcome: view.lastClosed.outcome, closeReason: view.lastClosed.closeReason}}
  };
  return JSON.parse(JSON.stringify(out), (_key, v: unknown) => typeof v === 'string' && map.has(v) ? map.get(v) : v) as unknown;
}

describe('trip replay of the simulator v1 corpus (T16, T17; REG-001 to REG-008)', () => {
  it('has a hand-written trip expectation for each listed scenario, tagged with its evidence basis', () => {
    for (const id of SCENARIOS) {
      expect(existsSync(tripExpectedPath(id)), id).toBe(true);
      const expected = JSON.parse(readFileSync(tripExpectedPath(id), 'utf8')) as TripExpected;
      expect(expected.scenario).toBe(id);
      expect(expected.basis.length, id).toBeGreaterThan(0);
      expect(expected.authoredFrom.length, id).toBeGreaterThan(0);
    }
  });
  for (const id of SCENARIOS) it(`scenario ${id} meets its hand-written trip expectation`, () => {
    const scenario = readFixtureFile(scenarioPath(id)) as {seed: string; game: 'ets2' | 'ats'};
    const result = replayV1(scenario), replay = replayTrips(result);
    // The storage model commits exactly what the scripted client committed.
    expect(replay.storage.committedThrough(seededId(scenario.seed, 'plugin-session'))).toBe(result.ledger.committedThroughEventSeq);
    // The reducer state is plain data.
    expect(JSON.parse(JSON.stringify(replay.state))).toEqual(replay.state);
    const expected = JSON.parse(readFileSync(tripExpectedPath(id), 'utf8')) as TripExpected;
    expect(summarize(replay, scenario.seed, scenario.game)).toEqual({trips: expected.trips, attributions: expected.attributions, intervals: expected.intervals,
      coverage: expected.coverage, view: expected.view});
  });
});
